select
odr.id,odr.logistics_no,
odr.return_order_no, odr.return_status, odr.store_code,odr.distribution_type, odr.store_name, odr.wrh_code,odr.stock_code, odr.sku_count, odr.return_type,
odr.return_notice_order_id, odr.submit_time, odr.org_code, odr.biz_org_code, odr.apply_return_quantity, odr.apply_return_amount,
odr.audit_return_quantity, odr.audit_return_amount, odr.actual_return_quantity, odr.actual_return_amount, odr.is_reversal,odr.is_reversal_order,
odr.source_return_no,odr.store_area,odr.hd_return_no, odr.remark, odr.create_time, odr.is_delete, odr.updater,
odr.creator, odr.update_time,odr.return_order_reason, odr.receive_time,odr.app_remark,odr.delivery_order_no
from ord_dis_return odr

    and odr.is_delete = 0

    and odr.return_order_no = #{returnOrderNo,jdbcType=VARCHAR}


    and odr.return_status = #{returnStatus,jdbcType=VARCHAR}


    and odr.store_code = #{storeCode,jdbcType=VARCHAR}


        and odr.return_order_reason = #{returnOrderReason,jdbcType=VARCHAR}


    and odr.store_name like concat('%', #{storeName,jdbcType=VARCHAR}, '%')


        and odr.return_type = #{returnType,jdbcType=VARCHAR}


        and odr.wrh_code = #{wrhCode,jdbcType=VARCHAR}


        and odr.stock_code = #{stockCode,jdbcType=VARCHAR}


        and odr.stock_code in

            #{item}



        and exists(select odrd.id from ord_dis_return_detail odrd where odrd.return_order_id = odr.id

            and odrd.goods_code=#{goodsCode,jdbcType=VARCHAR}


            and odrd.goods_name like concat('%', #{goodsName}, '%')


            and exists (select  1 from gc_org_goods_info gogi where odrd.org_goods_id = gogi.id and left(gogi.org_sort,2) in

                #{sort}

            )

        and odrd.is_delete = 0)


        and odr.is_reversal=#{isReversal,jdbcType=INTEGER}


        and odr.is_reversal_order=#{isReversalOrder,jdbcType=INTEGER}


        and odr.biz_org_code=#{bizOrgCode,jdbcType=VARCHAR}


        and odr.store_area = #{storeArea,jdbcType=VARCHAR}


        and odr.create_time between #{startTime} and #{endTime}


        and odr.receive_time >= #{receiveTimeBegin}


        and odr.receive_time <= #{receiveTimeEnd}


        and date_format(odr.create_time, '%Y-%m') = #{createMonth}


        and odr.logistics_no = #{logisticsNo}


order by odr.create_time desc,odr.id desc

