select
odr.return_order_no, odr.biz_org_code, odr.wrh_code, odr.stock_code, odr.store_code, odr.store_name, odr.return_status, odr.return_type,
odr.return_order_reason, odr.creator, odr.create_time, odr.remark, odrd.line, odrd.goods_code, odrd.apply_return_quantity, odrd.apply_package_quantity,
odrd.return_unit_price, odrd.vendor_code, odrd.return_reason, odrd.audit_return_quantity, odrd.audit_package_quantity, odrd.audit_return_amount
from ord_dis_return odr
inner join ord_dis_return_detail odrd on odrd.return_order_id = odr.id and odrd.is_delete = 0

     odr.is_delete = 0

        and odr.return_order_no = #{returnOrderNo,jdbcType=VARCHAR}


        and odr.return_status = #{returnStatus,jdbcType=VARCHAR}


        and odr.store_code = #{storeCode,jdbcType=VARCHAR}


        and odr.return_order_reason = #{returnOrderReason,jdbcType=VARCHAR}


        and odr.store_name like concat('%', #{storeName,jdbcType=VARCHAR}, '%')


        and odr.return_type = #{returnType,jdbcType=VARCHAR}


        and odr.wrh_code = #{wrhCode,jdbcType=VARCHAR}


        and odr.stock_code = #{stockCode,jdbcType=VARCHAR}


        and odr.stock_code in

            #{item}



        and odrd.goods_code=#{goodsCode,jdbcType=VARCHAR}


        and odrd.goods_name like concat('%', #{goodsName}, '%')


        and odr.is_reversal=#{isReversal,jdbcType=INTEGER}


        and odr.is_reversal_order=#{isReversalOrder,jdbcType=INTEGER}


        and odr.biz_org_code=#{bizOrgCode,jdbcType=VARCHAR}


        and odr.store_area = #{storeArea,jdbcType=VARCHAR}


        and odr.create_time >= #{startTime}


        and odr.create_time <= #{endTime}


        and odr.receive_time >= #{receiveTimeBegin}


        and odr.receive_time <= #{receiveTimeEnd}


        and date_format(odr.create_time, '%Y-%m') = #{createMonth}


        and odr.logistics_no = #{logisticsNo}


